export function DateRangePicker({
  label = "{{label}}",
  start = "{{start}}",
  end = "{{end}}",
  accent = "{{accent}}",
  required = {{required}},
}) {
  const inputStyle = {
    width: "100%", boxSizing: "border-box", padding: "9px 10px", font: "inherit", color: "#241430",
    background: "#FAF7F2", border: "1.5px solid #24143040", borderRadius: 8,
  };
  return (
    <fieldset style={{ maxWidth: 340, fontFamily: "system-ui, sans-serif", fontSize: 14, color: "#241430", border: "none", padding: 0, margin: 0 }}>
      <legend style={{ fontWeight: 500, marginBottom: 6, padding: 0 }}>{label}{required && " *"}</legend>
      <div style={{ display: "flex", alignItems: "flex-end", gap: 8 }}>
        <label style={{ display: "block", flex: 1 }}>
          <span style={{ display: "block", marginBottom: 4, fontSize: 12, color: "#24143099" }}>Start</span>
          <input type="date" defaultValue={start} required={required} autoComplete="off" style={inputStyle} />
        </label>
        <span aria-hidden="true" style={{ paddingBottom: 10, color: "#24143080" }}>&#8594;</span>
        <label style={{ display: "block", flex: 1 }}>
          <span style={{ display: "block", marginBottom: 4, fontSize: 12, color: "#24143099" }}>End</span>
          <input type="date" defaultValue={end} required={required} autoComplete="off" style={{ ...inputStyle, borderColor: accent }} />
        </label>
      </div>
    </fieldset>
  );
}
